func decodeAuthorDirect(s *orm.DirectScanner, c plan.OutCol, raw *orm.ScanValue, r *AuthorRow) error {
	v, err := s.Decode(c, raw.Value())
	if err != nil {
		return err
	}
	assignAuthorValue(r, c.Name, v)
	return nil
}

// scanAuthorDirect scans the default flat projection into generated typed
// fields. Codec and datetime outputs use named temporary scan values.
func scanAuthorDirect(s *orm.DirectScanner) (*AuthorRow, error) {
	a := s.Assemble()
	_ = a
	r := &AuthorRow{}
	r.Binding = s.Binding()
	var rawCreatedTs orm.ScanValue
	var rawUpdatedTs orm.ScanValue
	var rawDisplayStartDt orm.ScanValue
	var rawDisplayEndDt orm.ScanValue
	var rawStartDt orm.ScanValue
	var rawEndDt orm.ScanValue
	var rawAesHexEmail orm.ScanValue
	var rawAesHexPhone orm.ScanValue
	var rawIp orm.ScanValue
	if err := s.Scan(
		&r.Seq,
		&r.Name,
		&rawCreatedTs,
		&rawUpdatedTs,
		&r.IsClose,
		&r.IsDisplay,
		&rawDisplayStartDt,
		&rawDisplayEndDt,
		&r.IsAllday,
		&r.TargetClubReaderCount,
		&r.SuccessCount,
		&r.ReaderCount,
		&r.ReadCount,
		&r.PhotoUrl,
		&r.UserSeq,
		&r.ServiceSeq,
		&r.ServiceRegionSeq,
		&r.ServiceMemberSeq,
		&rawStartDt,
		&rawEndDt,
		&r.Uuid,
		&r.IsSingleWork,
		&r.LikeCount,
		&rawAesHexEmail,
		&rawAesHexPhone,
		&r.Price,
		&rawIp,
	); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[2], &rawCreatedTs, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[3], &rawUpdatedTs, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[6], &rawDisplayStartDt, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[7], &rawDisplayEndDt, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[18], &rawStartDt, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[19], &rawEndDt, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[23], &rawAesHexEmail, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[24], &rawAesHexPhone, r); err != nil {
		return nil, err
	}
	if err := decodeAuthorDirect(s, a.Columns[26], &rawIp, r); err != nil {
		return nil, err
	}
	r.SetProjection(s.Projection())
	r.Mark("author", []string{"seq"}, []any{r.Seq})
	if r.Has("updated_ts") {
		r.SnapshotVersion(r.UpdatedTs)
	}
	return r, nil
}

// scanAuthor maps a positional row slice onto the struct, its joined
// children (same row) and its relation children (rows of later steps).
func scanAuthor(vals []any, a *plan.Assemble, rs *orm.Rows) *AuthorRow {
	r := &AuthorRow{}
	r.Binding = rs.Binding
	for _, c := range a.Columns {
		assignAuthorValue(r, c.Name, vals[c.Index])
	}
	for _, ch := range a.Children {
		switch ch.Rel {
		case "service":
			if ch.Kind == "join" {
				if orm.JoinPresent(vals, ch.Assemble) {
					r.Service = scanService(vals, ch.Assemble, rs)
				}
			} else if rows := rs.Related(ch, vals); len(rows) > 0 {
				r.Service = scanService(rows[0], rs.StepAssemble(ch), rs)
			}
		case "service_member":
			if ch.Kind == "join" {
				if orm.JoinPresent(vals, ch.Assemble) {
					r.ServiceMember = scanServiceMember(vals, ch.Assemble, rs)
				}
			} else if rows := rs.Related(ch, vals); len(rows) > 0 {
				r.ServiceMember = scanServiceMember(rows[0], rs.StepAssemble(ch), rs)
			}
		case "service_region":
			if ch.Kind == "join" {
				if orm.JoinPresent(vals, ch.Assemble) {
					r.ServiceRegion = scanServiceRegion(vals, ch.Assemble, rs)
				}
			} else if rows := rs.Related(ch, vals); len(rows) > 0 {
				r.ServiceRegion = scanServiceRegion(rows[0], rs.StepAssemble(ch), rs)
			}
		case "user":
			if ch.Kind == "join" {
				if orm.JoinPresent(vals, ch.Assemble) {
					r.User = scanUser(vals, ch.Assemble, rs)
				}
			} else if rows := rs.Related(ch, vals); len(rows) > 0 {
				r.User = scanUser(rows[0], rs.StepAssemble(ch), rs)
			}
		}
	}
	r.SetProjection(rs.Projection(a))
	r.Mark("author", []string{"seq"}, []any{r.Seq})
	if r.Has("updated_ts") {
		r.SnapshotVersion(r.UpdatedTs)
	}
	return r
}

// ToArray is the row's array form (what PHP's toArray() and Rust's to_map() give):
// projected columns minus drop_child_key ones, extra outputs, loaded relations,
// and flattened one-relations merged in (this row's keys win).
func (r *AuthorRow) ToArray() (map[string]any, error) {
	m := make(map[string]any, len(r.Selected()))
	for _, name := range r.Selected() {
		if r.Hidden(name) {
			continue
		}
		switch name {
		case "seq":
			m[name] = r.Seq
		case "name":
			m[name] = r.Name
		case "description":
			m[name] = func() any {
				if r.Description == nil {
					return nil
				}
				return *r.Description
			}()
		case "created_ts":
			m[name] = orm.FormatTime(r.CreatedTs)
		case "updated_ts":
			m[name] = orm.FormatTime(r.UpdatedTs)
		case "is_close":
			m[name] = r.IsClose
		case "is_display":
			m[name] = r.IsDisplay
		case "display_start_dt":
			m[name] = func() any {
				if r.DisplayStartDt == nil {
					return nil
				}
				return orm.FormatTime(*r.DisplayStartDt)
			}()
		case "display_end_dt":
			m[name] = func() any {
				if r.DisplayEndDt == nil {
					return nil
				}
				return orm.FormatTime(*r.DisplayEndDt)
			}()
		case "is_allday":
			m[name] = r.IsAllday
		case "target_club_reader_count":
			m[name] = r.TargetClubReaderCount
		case "success_count":
			m[name] = r.SuccessCount
		case "reader_count":
			m[name] = r.ReaderCount
		case "read_count":
			m[name] = r.ReadCount
		case "photo_url":
			m[name] = func() any {
				if r.PhotoUrl == nil {
					return nil
				}
				return *r.PhotoUrl
			}()
		case "user_seq":
			m[name] = r.UserSeq
		case "service_seq":
			m[name] = r.ServiceSeq
		case "service_region_seq":
			m[name] = r.ServiceRegionSeq
		case "service_member_seq":
			m[name] = r.ServiceMemberSeq
		case "start_dt":
			m[name] = orm.FormatTime(r.StartDt)
		case "end_dt":
			m[name] = orm.FormatTime(r.EndDt)
		case "uuid":
			m[name] = func() any {
				if r.Uuid == nil {
					return nil
				}
				return *r.Uuid
			}()
		case "is_single_work":
			m[name] = r.IsSingleWork
		case "like_count":
			m[name] = r.LikeCount
		case "aes_key_version":
			m[name] = r.AesKeyVersion
		case "aes_hex_email":
			m[name] = func() any {
				if r.AesHexEmail == nil {
					return nil
				}
				return *r.AesHexEmail
			}()
		case "email_blind_index":
			m[name] = func() any {
				if r.EmailBlindIndex == nil {
					return nil
				}
				return *r.EmailBlindIndex
			}()
		case "aes_hex_phone":
			m[name] = func() any {
				if r.AesHexPhone == nil {
					return nil
				}
				return *r.AesHexPhone
			}()
		case "phone_blind_index":
			m[name] = func() any {
				if r.PhoneBlindIndex == nil {
					return nil
				}
				return *r.PhoneBlindIndex
			}()
		case "price":
			m[name] = func() any {
				if r.Price == nil {
					return nil
				}
				return *r.Price
			}()
		case "ip":
			m[name] = func() any {
				if r.Ip == nil {
					return nil
				}
				return *r.Ip
			}()
		case "gz_extend":
			m[name] = r.GzExtend
		case "json_setting":
			m[name] = r.JsonSetting
		case "jsons_tags":
			m[name] = r.JsonsTags
		case "base64_extra":
			m[name] = r.Base64Extra
		case "serialize_data":
			m[name] = r.SerializeData
		default:
			m[name] = r.Extra(name)
		}
	}
	if r.RelLoaded("service") {
		if r.Service != nil {
			child, err := r.Service.ToArray()
			if err != nil {
				return nil, err
			}
			m["service"] = child
		} else {
			m["service"] = nil
		}
	}
	if r.RelLoaded("service_member") {
		if r.ServiceMember != nil {
			child, err := r.ServiceMember.ToArray()
			if err != nil {
				return nil, err
			}
			m["service_member"] = child
		} else {
			m["service_member"] = nil
		}
	}
	if r.RelLoaded("service_region") {
		if r.ServiceRegion != nil {
			child, err := r.ServiceRegion.ToArray()
			if err != nil {
				return nil, err
			}
			m["service_region"] = child
		} else {
			m["service_region"] = nil
		}
	}
	if r.RelLoaded("user") {
		if r.User != nil {
			child, err := r.User.ToArray()
			if err != nil {
				return nil, err
			}
			m["user"] = child
		} else {
			m["user"] = nil
		}
	}
	for _, rel := range r.Flat() {
		if child, ok := m[rel].(map[string]any); ok {
			orm.MergeFlat(m, child)
		}
	}
	return m, nil
}

