// AuthorQuery builds a statement over author: Author() → Using(ctx, db) → chain → terminal().
type AuthorQuery struct {
	binding orm.Binding
	q       *orm.Q
	keyFn   func(*AuthorRow) orm.Key // KeyByFn: client-side keying of the root collection
}

// KeyByFn keys the root collection by a function of each row (relations key by keyBy<Col>).
func (q *AuthorQuery) KeyByFn(fn func(*AuthorRow) orm.Key) *AuthorQuery { q.keyFn = fn; return q }

// Req exposes the underlying request (debugging, plan inspection).
func (q *AuthorQuery) Req() *orm.Req { return q.q.Req }

// Author starts a query over author.
func Author() *AuthorQuery { return &AuthorQuery{q: orm.NewQ(mustEngine(), "author")} }

// Using selects the context and pool or transaction for this query.
func (q *AuthorQuery) Using(ctx context.Context, ex orm.Exec) *AuthorQuery {
	q.binding = orm.NewBinding(ctx, ex)
	return q
}

// AESStatus returns row counts by stored AES key version.
func (q *AuthorQuery) AESStatus(keyring orm.AESKeyring) (orm.AESRotationStatus, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.AESRotationStatus{}, err
	}
	return ex.DB().AESStatus(ctx, ex, orm.AESRotationSpec{Table: "author", PrimaryKeys: []string{"seq"}, VersionColumn: "aes_key_version"}, keyring)
}

// RotateAES re-encrypts every pending AES row to the keyring current version.
func (q *AuthorQuery) RotateAES(keyring orm.AESKeyring) (int, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return 0, err
	}
	return ex.DB().RotateAESRows(ctx, ex, orm.AESRotationSpec{
		Table: "author", PrimaryKeys: []string{"seq"}, VersionColumn: "aes_key_version",
		BatchSize: 1000,
		Columns: []orm.AESRotationColumn{
			{Name: "aes_hex_email", Styles: []string{"aes", "hex"}},
			{Name: "aes_hex_phone", Styles: []string{"aes", "hex"}},
		},
	}, keyring)
}

// Using selects the context and pool or transaction for this loaded row.
func (r *AuthorRow) Using(ctx context.Context, ex orm.Exec) *AuthorRow {
	r.Binding = orm.NewBinding(ctx, ex)
	return r
}

