// Terminals.
func (q *AuthorQuery) Get() (*AuthorRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "one"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsAuthorDirect, scanAuthorDirect); used {
		if err != nil || len(direct) == 0 {
			return nil, err
		}
		return direct[0], nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil || len(rows.Data) == 0 {
		return nil, err
	}
	return scanAuthor(rows.Data[0], rows.Assemble, rows), nil
}

func (q *AuthorQuery) Gets() (*orm.Collection[AuthorRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsAuthorDirect, scanAuthorDirect); used {
		if err != nil {
			return nil, err
		}
		return collectAuthorDirect(direct, q.keyFn), nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	return collectAuthor(rows, q.keyFn), nil
}

// Stream visits independently owned rows without accumulating the complete result.
// Returning false stops the query and closes its database cursor.
func (q *AuthorQuery) Stream(visit func(*AuthorRow) bool) (orm.StreamResult, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.StreamResult{}, err
	}
	if visit == nil {
		return orm.StreamResult{}, &ir.Error{Code: orm.CodeIrInvalid, Msg: "stream visitor is required"}
	}
	q.q.Req.IR.Kind = "all"
	return orm.Stream(ctx, ex, q.q.Req, func(vals []any, rows *orm.Rows) bool {
		return visit(scanAuthor(vals, rows.Assemble, rows))
	})
}

