func collectAuthor(rows *orm.Rows, keyFn func(*AuthorRow) orm.Key) *orm.Collection[AuthorRow] {
	c := orm.NewCollection[AuthorRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanAuthor(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectAuthorDirect(rows []*AuthorRow, keyFn func(*AuthorRow) orm.Key) *orm.Collection[AuthorRow] {
	c := orm.NewCollection[AuthorRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.Seq}), r)
		}
	}
	return c
}

// GetsAfter reads the next keyset page. An empty cursor starts at the first row.
func (q *AuthorQuery) GetsAfter(cursor string, per int) (*orm.KeysetPage[AuthorRow], error) {
	if err := q.q.Keyset("after", cursor, per, []string{"seq"}); err != nil {
		return nil, err
	}
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	items := collectAuthor(rows, q.keyFn)
	return orm.KeysetPageFromRows(rows, items, q.q.Req.IR.Order)
}

// GetsBefore reads the previous keyset page and restores the requested order.
func (q *AuthorQuery) GetsBefore(cursor string, per int) (*orm.KeysetPage[AuthorRow], error) {
	if err := q.q.Keyset("before", cursor, per, []string{"seq"}); err != nil {
		return nil, err
	}
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	orm.ReverseRows(rows)
	items := collectAuthor(rows, q.keyFn)
	return orm.KeysetPageFromRows(rows, items, q.q.Req.IR.Order)
}

