func (q *AuthorQuery) Paginate(page, per int) (*orm.Page[AuthorRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	if per <= 0 {
		return nil, &ir.Error{Code: "IR_INVALID", Msg: "per must be positive"}
	}
	if page < 1 {
		page = 1
	}
	q.q.Req.IR.Kind = "paginate"
	q.q.Node.Limit = &ir.Limit{Offset: (page - 1) * per, Count: per}
	rows, total, err := orm.Paginate(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	pages := (total + int64(per) - 1) / int64(per)
	return &orm.Page[AuthorRow]{Items: collectAuthor(rows, q.keyFn), Total: total, Pages: pages, Current: int64(page), Per: int64(per)}, nil
}

func (q *AuthorQuery) Insert() (*AuthorRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "insert"
	id, _, err := orm.Write(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	return Author().Using(ctx, ex).SeqEq(int64(id)).Get()
}

// Save updates when every primary-key column was assigned and inserts when none was assigned.
func (q *AuthorQuery) Save() (*AuthorRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	keys, ok, err := q.q.MoveKeysToWhere([]string{"seq"})
	if err != nil {
		return nil, err
	}
	if !ok {
		return q.Insert()
	}
	q.q.Req.IR.Kind = "update"
	if _, _, err := orm.Write(ctx, ex, q.q.Req); err != nil {
		return nil, err
	}
	return Author().Using(ctx, ex).SeqEq(keys[0].(int64)).Get()
}

// Update applies the draft's assignments to every row the WHERE matches (the engine rejects a missing WHERE).
func (q *AuthorQuery) Update() (int64, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return 0, err
	}
	q.q.Req.IR.Kind = "update"
	_, affected, err := orm.Write(ctx, ex, q.q.Req)
	return affected, err
}

// Delete removes every row the WHERE matches (the engine rejects a missing WHERE).
func (q *AuthorQuery) Delete() (int64, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return 0, err
	}
	q.q.Req.IR.Kind = "delete"
	_, affected, err := orm.Write(ctx, ex, q.q.Req)
	return affected, err
}

// BatchInsert executes typed query drafts in one transaction with bounded chunks.
func (q *AuthorQuery) BatchInsert(rows []*AuthorQuery, options orm.BatchOptions) (orm.BatchResult, error) {
	return q.batchWrite(rows, "insert", options)
}

// BatchUpsert executes typed insert drafts with their on-duplicate assignments in one transaction.
func (q *AuthorQuery) BatchUpsert(rows []*AuthorQuery, options orm.BatchOptions) (orm.BatchResult, error) {
	return q.batchWrite(rows, "insert", options)
}

// BatchUpdate updates typed query drafts in one transaction.
func (q *AuthorQuery) BatchUpdate(rows []*AuthorQuery, options orm.BatchOptions) (orm.BatchResult, error) {
	return q.batchWrite(rows, "update", options)
}

// BatchDelete deletes typed query drafts in one transaction.
func (q *AuthorQuery) BatchDelete(rows []*AuthorQuery, options orm.BatchOptions) (orm.BatchResult, error) {
	return q.batchWrite(rows, "delete", options)
}
func (q *AuthorQuery) batchWrite(rows []*AuthorQuery, kind string, options orm.BatchOptions) (orm.BatchResult, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.BatchResult{}, err
	}
	requests := make([]*orm.Req, len(rows))
	for i, row := range rows {
		if row == nil || row.q == nil {
			return orm.BatchResult{}, &ir.Error{Code: "IR_INVALID", Msg: "batch row is nil"}
		}
		requests[i] = row.q.Req
	}
	return orm.BatchWrite(ctx, ex, requests, kind, options)
}

// SQL renders the main statement as All would run it, without executing: secret binds show as "$SECRET".
func (q *AuthorQuery) SQL() (*orm.Statement, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	return orm.SQL(ctx, ex, q.q.Req)
}

func (q *AuthorQuery) GetBySeq(v int64) (*AuthorRow, error) {
	return q.SeqEq(v).Get()
}

// GetByUuid applies the equality predicates for the declared unique key.
func (q *AuthorQuery) GetByUuid(v0 string) (*AuthorRow, error) {
	return q.Uuid(v0).Get()
}
